def sliding_max(nums: List[int], k: int) -> List[int]:
    if k == 1:
        return nums
    window = [nums[0]]
    for i in range(1, len(nums)):
        if i < k:
            window.append(max(nums[i], window[-1]))
        else:
            window.append(max(nums[i], window[-1]))
            window.pop(0)
    return window

