def topo_sort(n: int, edges: list[tuple[int, int]]) -> list[int]:
    from heapq import heappop, heappush
    from collections import defaultdict, deque

    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)

    visited = {node: False for node in range(n)}
    cycle_tracker = {node: False for node in range(n)}

    queue = deque()
    for node in range(n):
        if len(adj_list[node]) == 0:
            queue.append(node)

    result = []
    while queue:
        node = queue.popleft()
        result.append(node)
        visited[node] = True
        for neighbor in adj_list[node]:
            if not visited[neighbor]:
                cycle_tracker[neighbor] = True
                if cycle_tracker[neighbor]:
                    return []
                adj_list[neighbor].remove(node)
                if len(adj_list[neighbor]) == 0:
                    queue.append(neighbor)

    for node in range(n):
        if not visited[node]:
            return []

    return result

