    # Step 1: Find the first element from the right that is smaller than the element next to it.
    pivot = -1
    for i in range(len(nums) - 1, 0, -1):
        if nums[i - 1] < nums[i]:
            pivot = i - 1
            break

    # Step 2: If no such element is found, the list is already the highest permutation.
    if pivot == -1:
        return sorted(nums)

    # Step 3: Find the smallest element to the right of the pivot that is larger than the pivot.
    swap = len(nums) - 1
    for i in range(len(nums) - 1, pivot, -1):
        if nums[i] > nums[pivot]:
            swap = i
            break

    # Step 4: Swap the pivot and the swap element.
    nums[pivot], nums[swap] = nums[swap], nums[pivot]

    # Step 5: Reverse the elements to the right of the pivot.
    nums[pivot + 1:] = reversed(nums[pivot + 1:])

