def dijkstra(n: int, edges: List[Tuple[int, int, int]], src: int) -> List[int]:
    # Graph is represented as an adjacency list
    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    # Priority queue to store nodes by their distance from the source
    pq = [(0, src)]
    # Distance array to store the shortest distance from source to each node
    dist = [float('inf')] * n
    dist[src] = 0

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            distance = d + w
            if distance < dist[v]:
                dist[v] = distance
                heapq.heappush(pq, (distance, v))

    # Replace inf distances with -1 for unreachable nodes
    dist = [-1 if d == float('inf') else d for d in dist]
    return dist

