    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)

    visiting = set()
    visited = set()
    stack = []

    def dfs(node):
        if node in visiting:
            return False
        if node in visited:
            return True

        visiting.add(node)
        for neighbor in graph[node]:
            if not dfs(neighbor):
                return False
        visiting.remove(node)
