    def helper(s, index, memo):
        if index == len(s):
            return 1
        if s[index] == '0':
            return 0
        if index == len(s) - 1:
            return 1

        if index in memo:
            return memo[index]

        count = helper(s, index + 1, memo)
        if index + 2 <= len(s) and int(s[index:index+2]) <= 26:
            count += helper(s, index + 2, memo)

        memo[index] = count
        return count

    memo = {}
    return helper(s, 0, memo)

