def max_consecutive_ones(bits: list[int]) -> int:
    max_streak = 0
    current_streak = 0
    for bit in bits:
        if bit == 1:
            current_streak += 1
            max_streak = max(max_streak, current_streak)
        else:
            current_streak = 0
    return max_streak

def spiral_order(matrix: list[list[int]]) -> list[int]:
    if not matrix or not matrix[0]:
        return []

    result = []
    rows, cols = len(matrix), len(matrix[0])
    top, bottom, left, right = 0, rows - 1, 0, cols - 1

    while top <= bottom and left <= right:
        # Traverse top row
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1

        # Traverse right column
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1

        if top <= bottom:
            # Traverse bottom row
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1

        if left <= right:
            # Traverse left column
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1

    return result

def n_queens(n: int) -> int:
    def place_queen(board, row, columns, pos_diags, neg_diags):
        if row == n:
            return 1
        solutions = 0
        for col in range(n):
            if col not in columns and (row + col) not in pos_diags and (row - col) not in neg_diags:
                columns.add(col)
                pos_diags.add(row + col)
                neg_diags.add(row - col)
                solutions += place_queen(board, row + 1, columns, pos_diags, neg_diags)
                columns.remove(col)
                pos_diags.remove(row + col)
                neg_diags.remove(row - col)
        return solutions

    return place_queen(set(), 0, set(), set(), set())

from collections import deque

def count_islands(grid: list[str]) -> int:
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    island_count = 0

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == '1':
                island_count += 1
                queue = deque([(row, col)])
                while queue:
                    r, c = queue.popleft()
                    if grid[r][c] == '0':
                        continue
                    grid[r] = grid[r][:c] + '0' + grid[r][c+1:]  # Mark as visited
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '1':
                            queue.append((nr, nc))

    return island_count

def lru_misses(capacity: int, requests: list[int]) -> int:
    cache = {}
    order = deque()
    misses = 0

    for request in requests:
        if request in cache:
            order.remove(request)
            order.appendleft(request)
        else:
            misses += 1
            if len(cache) == capacity:
                evicted = order.pop()
                del cache[evicted]
            cache[request] = None
            order.appendleft(request)

    return misses

def title_case(s: str) -> str:
    words = s.split(' ')
    modified_words = []
    for word in words:
        modified_word = word[0].upper() + word[1:].lower()
        modified_words.append(modified_word)
    return ' '.join(modified_words)

def count_vowels(s: str) -> int:
    s = s.lower()
    vowels = {'a', 'e', 'i', 'o', 'u'}
    return sum(1 for char in s if char in vowels)

def longest_palindrome(s: str) -> str:
    if not s:
        return ''

    start, end = 0, 0

    for i in range(len(s)):
        len1 = expand_around_center(s, i, i)
        len2 = expand_around_center(s, i, i + 1)
        max_len = max(len1, len2)

        if max_len > end - start:
            start = i - (max_len - 1) // 2
            end = i + max_len // 2

    return s[start:end + 1]

def expand_around_center(s: str, left: int, right: int) -> int:
    while left >= 0 and right < len(s) and s[left] == s[right]:
        left -= 1
        right += 1

    return right - left - 1

def is_leap_year(year: int) -> bool:
    if year % 4 != 0:
        return False
    elif year % 100 == 0:
        return year % 400 == 0
    else:
        return True

def next_permutation(nums: list[int]) -> list[int]:
    i = len(nums) - 2
    while i >= 0 and nums[i] >= nums[i + 1]:
        i -= 1
    if i == -1:
        nums.sort()
        return nums
    j = len(nums) - 1
    while nums[j] <= nums[i]:
        j -= 1
    nums[i], nums[j] = nums[j], nums[i]
    nums[i + 1:] = reversed(nums[i + 1:])
    return nums

import heapq

def dijkstra(n: int, edges: list[tuple[int, int, int]], src: int) -> list[int]:
    distances = [float('inf')] * n
    distances[src] = 0

    queue = [(0, src)]

    while queue:
        current_distance, current_vertex = heapq.heappop(queue)

        if current_distance > distances[current_vertex]:
            continue

        for neighbor, weight in [(v, w) for u, v, w in edges if u == current_vertex]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(queue, (distance, neighbor))

    return [dist if dist != float('inf') else -1 for dist in distances]

def sum_of_digits(n: int) -> int:
    n = abs(n)  # Make n positive
    return sum(int(digit) for digit in str(n))

def prime_factors(n: int) -> list[int]:
    factors = []
    divisor = 2
    while n > 1:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1
        if divisor * divisor > n:
            if n > 1:
                factors.append(n)
                break
    return factors

def decode_ways(s: str) -> int:
    if not s or s[0] == '0':
        return 0

    dp = [0] * (len(s) + 1)
    dp[0] = 1
    dp[1] = 1 if s[0] != '0' else 0

    for i in range(2, len(s) + 1):
        if s[i-1] != '0':
            dp[i] += dp[i-1]
        two_digit = int(s[i-2:i])
        if 10 <= two_digit <= 26:
            dp[i] += dp[i-2]

    return dp[-1]

def char_frequency(s: str) -> dict[str, int]:
    freq = {}
    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1
    return freq

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    intervals.sort(key=lambda x: x[0])

    merged = []

    for interval in intervals:
        if not merged or merged[-1][1] < interval[0]:
            merged.append(interval)
        else:
            merged[-1][1] = max(merged[-1][1], interval[1])

    return merged

def regex_match(s: str, p: str) -> bool:
    def matches(c1: str, c2: str) -> bool:
        return c1 == c2 or c2 == '.'

    i, j = 0, 0
    m, n = len(s), len(p)

    while i < m:
        if j < n and (p[j] == '?' or p[j] == '*'):
            if j < n and p[j] == '*':
                if matches(s[i], p[j-1]):
                    i += 1
                    continue
                else:
                    j += 1
            else:
                j += 1
        elif matches(s[i], p[j]):
            i += 1
            j += 1
        else:
            return False

    while j < n and p[j] == '*':
        j += 1

    return i == m and j == n

def second_largest(nums: list[int]) -> int | None:
    distinct_values = sorted(set(nums), reverse=True)
    if len(distinct_values) < 2:
        return None
    return distinct_values[1]

def parse_duration(s: str) -> int:
    unit_to_seconds = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    if not s:
        raise ValueError("Input string is empty")
    total_seconds = 0
    current_number = ''
    current_unit = ''
    for char in s:
        if char.isdigit():
            current_number += char
        elif char in unit_to_seconds:
            if current_number:
                total_seconds += int(current_number) * unit_to_seconds[current_unit]
                current_number = ''
            current_unit = char
        else:
            raise ValueError("Malformed string")
    if current_number and current_unit in unit_to_seconds:
        total_seconds += int(current_number) * unit_to_seconds[current_unit]
    return total_seconds

from typing import List

def group_anagrams(words: List[str]) -> List[List[str]]:
    anagrams = {}

    for word in words:
        # Create a tuple of the sorted characters of the word, which will be used as a key
        sorted_word = tuple(sorted(word))
        if sorted_word not in anagrams:
            anagrams[sorted_word] = []
        anagrams[sorted_word].append(word)

    # Sort the lists of anagrams alphabetically and then sort the groups by their first word
    sorted_anagrams = [sorted(group) for group in anagrams.values()]
    sorted_anagrams.sort(key=lambda x: x[0])

    return sorted_anagrams

def word_break(s: str, words: list[str]) -> bool:
    dp = [False] * (len(s) + 1)
    dp[0] = True

    for i in range(1, len(s) + 1):
        for j in range(i):
            if dp[j] and s[j:i] in words:
                dp[i] = True
                break

    return dp[len(s)]

def longest_common_prefix(strs: list[str]) -> str:
    if not strs:
        return ''

    prefix = strs[0]
    for s in strs[1:]:
        while s[:len(prefix)] != prefix:
            prefix = prefix[:-1]
            if not prefix:
                return ''
    return prefix

def edit_distance(a: str, b: str) -> int:
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize the first row and column
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Fill the matrix
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if a[i-1] == b[j-1] else 1
            dp[i][j] = min(dp[i-1][j] + 1,      # Deletion
                           dp[i][j-1] + 1,      # Insertion
                           dp[i-1][j-1] + cost) # Substitution

    return dp[m][n]

import ast

def evaluate(expr: str) -> int:
    class ExpressionEvaluator(ast.NodeVisitor):
        def visit_BinOp(self, node):
            left_value = self.visit(node.left)
            right_value = self.visit(node.right)
            if isinstance(node.op, (ast.Add, ast.Sub)):
                return left_value + right_value if isinstance(node.op, ast.Add) else left_value - right_value
            elif isinstance(node.op, (ast.Mult, ast.Div)):
                result = left_value * right_value if isinstance(node.op, ast.Mult) else int(left_value / right_value)
                return result
            else:
                raise ValueError(f"Unsupported operator {type(node.op).__name__}")

        def visit_Num(self, node):
            return node.n

        def visit_UnaryOp(self, node):
            if isinstance(node.op, ast.USub):
                return -self.visit(node.operand)
            else:
                raise ValueError(f"Unsupported operator {type(node.op).__name__}")

        def visit_UnaryExpr(self, node):
            return self.visit(node.operand)

        def visit_Call(self, node):
            if isinstance(node.func, ast.Name) and node.func.id == 'int':
                return self.visit(node.args[0])
            else:
                raise ValueError(f"Unsupported function call {node.func.id}")

        def visit_NameConstant(self, node):
            return node.value

        def visit_Str(self, node):
            return node.s

        def visit_Name(self, node):
            return node.id

        def generic_visit(self, node):
            raise ValueError(f"Unsupported node type {type(node).__name__}")

        def visit(self, node):
            result = super().visit(node)
            if isinstance(result, ast.AST):
                raise ValueError(f"Node {type(result).__name__} not evaluated")
            return result

    tree = ast.parse(expr, mode='eval').body
    evaluator = ExpressionEvaluator()
    return evaluator.visit(tree)

def longest_word(s: str) -> str:
    words = s.split()
    if not words:
        return ''
    longest = words[0]
    for word in words:
        if len(word) > len(longest):
            longest = word
    return longest

import re

def is_valid_ipv4(s: str) -> bool:
    if not re.match(r'^(\d{1,3}\.){3}\d{1,3}$', s):
        return False

    parts = s.split('.')

    for part in parts:
        if not re.match(r'^\d{1,3}$', part):
            return False

        num = int(part)
        if num < 0 or num > 255:
            return False

        if part != '0' and part.startswith('0'):
            return False

    return True

def digital_root(n: int) -> int:
