def lru_misses(capacity: int, requests: list[int]) -> int:
    cache = OrderedDict()
    misses = 0

    for request in requests:
        if request in cache:
            cache.move_to_end(request)
        else:
            if len(cache) == capacity:
                cache.popitem(last=False)
            cache[request] = None
            misses += 1

    return misses

import heapq

def dijkstra(n: int, edges: list[tuple[int, int, int]], src: int) -> list[int]:
    distances = [float('inf')] * n
    distances[src] = 0

    queue = [(0, src)]

    while queue:
        current_dist, current_node = heapq.heappop(queue)

        if current_dist > distances[current_node]:
            continue

        for neighbor, weight in [(v, w) for u, v, w in edges if u == current_node]:
            distance = current_dist + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(queue, (distance, neighbor))

    return [dist if dist != float('inf') else -1 for dist in distances]

def prime_factors(n: int) -> list[int]:
    factors = []
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def next_permutation(nums: list[int]) -> list[int]:
    pivot_index = -1
    for i in range(len(nums) - 1, 0, -1):
        if nums[i - 1] < nums[i]:
            pivot_index = i - 1
            break

    if pivot_index == -1:
        return sorted(nums)

    successor_index = -1
    for j in range(len(nums) - 1, pivot_index, -1):
        if nums[j] > nums[pivot_index]:
            successor_index = j
            break

    nums[pivot_index], nums[successor_index] = nums[successor_index], nums[pivot_index]
    nums[pivot_index + 1:] = reversed(nums[pivot_index + 1:])

    return nums

def decode_ways(s: str) -> int:
    if not s or s[0] == '0':
        return 0

    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1  # Empty string has one way to decode
    dp[1] = 1 if s[0] != '0' else 0

    for i in range(2, n + 1):
        if s[i-1] != '0':
            dp[i] += dp[i-1]
        two_digit = int(s[i-2:i])
        if 10 <= two_digit <= 26:
            dp[i] += dp[i-2]

    return dp[n]

