from collections import deque

def sliding_max(nums: list[int], k: int) -> list[int]:
    if not nums:
        return []

    deq = deque()
    result = []

    for i in range(len(nums)):
        # Remove elements out of the current window
        if deq and deq[0] == i - k:
            deq.popleft()

        # Remove elements smaller than the current element from the back
        while deq and nums[deq[-1]] < nums[i]:
            deq.pop()

        # Add the current element's index to the back
        deq.append(i)

        # Append the maximum value for the current window
        if i >= k - 1:
            result.append(nums[deq[0]])

    return result

def topo_sort(n: int, edges: list[tuple[int, int]]) -> list[int]:
    from collections import defaultdict, deque

    adj_list = defaultdict(list)
    indegree = [0] * n

    for u, v in edges:
        adj_list[u].append(v)
        indegree[v] += 1

    queue = deque([i for i in range(n) if indegree[i] == 0])
    order = []

    while queue:
        node = queue.popleft()
        order.append(node)

        for neighbor in adj_list[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    if len(order) == n:
        return order
    else:
        return []

def paths_with_obstacles(grid: list[list[int]]) -> int:
    n, m = len(grid), len(grid[0])

    if grid[0][0] == 1 or grid[n-1][m-1] == 1:
        return 0

    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[n-1][m-1]

def knapsack(weights: list[int], values: list[int], capacity: int) -> int:
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(1, capacity + 1):
            if weights[i - 1] <= w:
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - weights[i - 1]] + values[i - 1])
            else:
                dp[i][w] = dp[i - 1][w]

    return dp[n][capacity]

