    for u, v in edges:
        adj_list[u].append(v)

    visited = [False] * n
    dfs_visited = [False] * n
    order = []
    stack = []

    def dfs(node):
        stack.append(node)
        dfs_visited[node] = True
        for neighbor in adj_list[node]:
            if dfs_visited[neighbor]:
                return
            if not visited[neighbor]:
                dfs(neighbor)
        order.append(stack.pop())
