def edit_distance(a: str, b: str) -> int:
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],      # deletion
                                    dp[i][j - 1],      # insertion
                                    dp[i - 1][j - 1])  # substitution
    return dp[m][n]

def evaluate(expr: str) -> int:
    def get_next_token(i):
        while i < len(expr):
            if expr[i] == ' ':
                i += 1
            elif expr[i] in '+-*/()':
                return i, expr[i]
            else:  # it's a number
                start = i
                while i < len(expr) and expr[i].isdigit():
                    i += 1
                return i, int(expr[start:i])
        return i, None

    def parse_factor(i):
        i, token = get_next_token(i)
        if token == '(':
            i, result = parse_expression(i+1)
            i = get_next_token(i+1)[0]  # consume ')'
            return i, result
        else:
            return i, token

    def parse_term(i):
        i, result = parse_factor(i)
        while i < len(expr):
            i, token = get_next_token(i)
            if token == '*':
                i, value = parse_factor(i+1)
                result *= value
            elif token == '/':
                i, value = parse_factor(i+1)
                result = int(result / value)  # truncating division
            else:
                break
        return i, result

    def parse_expression(i):
        i, result = parse_term(i)
        while i < len(expr):
            i, token = get_next_token(i)
            if token == '+':
                i, value = parse_term(i+1)
                result += value
            elif token == '-':
                i, value = parse_term(i+1)
                result -= value
            else:
                break
        return i, result

    _, result = parse_expression(0)
    return result

