def topo_sort(n: int, edges: list[tuple[int, int]]) -> list[int]:
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    def dfs(node, visited, rec_stack, result):
        visited[node] = True
        rec_stack[node] = True

        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor, visited, rec_stack, result):
                    return True
            elif rec_stack[neighbor]:
                return True

        result.append(node)
        rec_stack[node] = False
        return False

    visited = [False] * n
    rec_stack = [False] * n
    result = []

    for i in range(n):
        if not visited[i]:
            if dfs(i, visited, rec_stack, result):
                return []

    return result[::-1]

