def count_islands(grid: list[str]) -> int:
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    island_count = 0
    land = [[int(cell) for cell in row] for row in grid]

    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            row, col = stack.pop()
            if 0 <= row < rows and 0 <= col < cols and land[row][col] == 1:
                land[row][col] = 0
                stack.extend([(row+1, col), (row-1, col), (row, col+1), (row, col-1)])

    for r in range(rows):
        for c in range(cols):
            if land[r][c] == 1:
                dfs(r, c)
                island_count += 1

    return island_count

