def dijkstra(n, edges, src):
    # Initialize distances with infinity and set the source distance to zero
    distances = [float('inf')] * n
    distances[src] = 0

    # Priority queue to select the node with the minimum distance
    queue = [(0, src)]

    while queue:
        current_distance, current_vertex = heapq.heappop(queue)

        # If this node has already been visited, skip it
        if current_distance > distances[current_vertex]:
            continue

        # Explore the neighbors of the current vertex
        for edge in edges:
            if edge[0] == current_vertex:
                neighbor, weight = edge[1], edge[2]
                distance = current_distance + weight

                # If a shorter path to the neighbor is found
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))

    # Replace unreachable nodes with -1
    for i in range(n):
        if distances[i] == float('inf'):
            distances[i] = -1

    return distances
