    operators = re.findall(r'[\+\-\*/()]', expr)
    operands = re.findall(r'\d+', expr)

    stack = []
    for token in operators + operands:
        if token.isdigit():
            stack.append(int(token))
        else:
            a = stack.pop()
            b = stack.pop()
            prec_a = op_priority.get(a, 3)  # default to lowest precedence
            prec_b = op_priority.get(token, 3)
            if prec_a > prec_b or (prec_a == prec_b and token == '('):
                stack.append(a + (b * (token != ')')) if token == '*' else a + (b * (token != '/')) if token == '/' else a + (b + (token != '-')) if token == '-' else a + (b - (token != '+'))

    return stack[0]

