def paths_with_obstacles(grid):
    rows, cols = len(grid), len(grid[0])
    dp = [[0] * cols for _ in range(rows)]

    # base case: only one cell, either blocked or open
    if rows == 1 and cols == 1 and grid[0][0] == 0:
        dp[0][0] = 1
    elif rows == 1 and grid[0][0] == 1:
        dp[0][0] = 0
    elif cols == 1 and grid[0][0] == 1:
        dp[0][0] = 0

    # populate dp using dynamic programming
    for i in range(1, rows):
        if grid[i][0] == 1:
            break
        dp[i][0] += dp[i - 1][0]

    for j in range(1, cols):
        if grid[0][j] == 1:
            continue
        for i in range(1, rows):
            dp[i][j] += dp[i - 1][j] + dp[i][j - 1] if grid[i][j] == 0 else 0

    # last cell must be open
    if grid[rows - 1][cols - 1] == 1:
        return 0

    return dp[rows - 1][cols - 1]

