def evaluate(expr: str) -> int:
    # Tokenize the expression
    tokens = expr.split()

    # Evaluate the expression
    result = 0
    for token in tokens:
        # If the token is a number, add it to the result
        if token.isdigit():
            result += int(token)
        # If the token is an operator, perform the operation
        elif token in "+-*/":
            # If the operator is + or -, add or subtract the result
            if token == "+":
                result += evaluate(tokens[tokens.index(token) + 1])
            elif token == "-":
                result -= evaluate(tokens[tokens.index(token) + 1])
            # If the operator is * or /, multiply or divide the result
            elif token == "*":
                result *= evaluate(tokens[tokens.index(token) + 1])
            elif token == "/":
                result //= evaluate(tokens[tokens.index(token) + 1])

    return result

