def sliding_max(nums: list[int], k: int) -> list[int]:
    """
    Return the maximum of each contiguous window of size k (1 <= k <= len(nums)), from left to right.
    The solution must run in O(n) time.
    """
    if not nums:
        return []

    if k <= 0:
        return []

    if k > len(nums):
        return [max(nums)]

    result = []
    dq = deque()  # Store indices

    for i in range(len(nums)):
        # Remove elements out of the window
        while dq and dq[0] <= i - k:
            dq.popleft()

        # Remove smaller elements from the deque
        while dq and nums[dq[-1]] <= nums[i]:
            dq.pop()

        dq.append(i)

        # The front of the deque is the index of the maximum element in the window
        if i >= k - 1:
            result.append(nums[dq[0]])

    return result

