    """
    Parse a duration string made of one or more <integer><unit> parts, with units d (days), h (hours), m (minutes), and s (seconds), in any order, e.g. '1h30m15s'.
    Return the total number of seconds.
    Raise ValueError for an empty or malformed string.
    """
    if not s:
        raise ValueError("Empty string")

    total_seconds = 0
    i = 0
    while i < len(s):
        if not s[i].isdigit():
            i += 1
            continue

        start = i
        while i < len(s) and s[i].isdigit():
            i += 1
        try:
            num = int(s[start:i])
        except ValueError:
            raise ValueError("Malformed string")

        if i < len(s):
            unit = s[i]
            if unit == 'd':
                total_seconds += num * 24 * 60 * 60
            elif unit == 'h':
                total_seconds += num * 60 * 60
            elif unit == 'm':
                total_seconds += num * 60
            elif unit == 's':
                total_seconds += num
            else:
                raise ValueError("Malformed string")
            i += 1
        else:
            raise ValueError("Malformed string")

    return total_seconds

