        while left >= 0 and right < n and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left + 1:right]

    for i in range(n):
        # Odd length palindromes
        palindrome1 = expand_around_center(i, i)
        if len(palindrome1) > len(longest):
            longest = palindrome1
        elif len(palindrome1) == len(longest) and palindrome1:
            if s.find(palindrome1) < s.find(longest):
                longest = palindrome1

        # Even length palindromes
        palindrome2 = expand_around_center(i, i + 1)
        if len(palindrome2) > len(longest):
            longest = palindrome2
        elif len(palindrome2) == len(longest) and palindrome2:
            if s.find(palindrome2) < s.find(longest):
                longest = palindrome2

    return longest

def matmul(a: list[list[float]], b: list[list[float]]) -> list[list[float]]:
    """
    Return the matrix product a x b. Raise ValueError if the number of columns of a differs from the number of rows of b.
    """
    rows_a = len(a)
    cols_a = len(a[0]) if rows_a > 0 else 0
    rows_b = len(b)
    cols_b = len(b[0]) if rows_b > 0 else 0

    if cols_a != rows_b:
        raise ValueError("Number of columns of a must equal the number of rows of b")

    result = [[0.0 for _ in range(cols_b)] for _ in range(rows_a)]

    for i in range(rows_a):
        for j in range(cols_b):
            for k in range(cols_a):
                result[i][j] += a[i][k] * b[k][j]

    return result

def roman_to_int(s: str) -> int:
