def topo_sort(n: int, edges: list[tuple[int, int]]) -> list[int]:
    """
    Nodes are 0..n-1 and each edge (u, v) means u must come before v.
    Return the lexicographically smallest topological ordering of all nodes,
    or [] if the graph contains a cycle.
    """
    in_degree = [0] * n
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    queue = []
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)
    queue.sort()

    result = []
    while queue:
        u = queue.pop(0)
        result.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
        queue.sort()

    if len(result) != n:
        return []
    else:
        return result

def parse_duration(s: str) -> int:
    """Parse a duration string made of one or more <integer><unit> parts,
    with units d (days), h (hours), m (minutes), and s (seconds), in any
    order, e.g. '1h30m15s'. Return the total number of seconds.
    Raise ValueError for an empty or malformed string.
    """
    if not s:
        raise ValueError("Empty string")

    total_seconds = 0
    i = 0
    while i < len(s):
        # Extract the integer part
        num_str = ""
        while i < len(s) and s[i].isdigit():
            num_str += s[i]
            i += 1
        if not num_str:
            raise ValueError("Malformed string")
        num = int(num_str)

        # Extract the unit
        if i == len(s):
            raise ValueError("Malformed string")
        unit = s[i]

        # Calculate the seconds and add to the total
        if unit == 'd':
            total_seconds += num * 24 * 60 * 60
        elif unit == 'h':
            total_seconds += num * 60 * 60
        elif unit == 'm':
            total_seconds += num * 60
        elif unit == 's':
            total_seconds += num
        else:
            raise ValueError("Malformed string")
        i += 1

    return total_seconds

