def regex_match(s: str, p: str) -> bool:
    """
    Return True if pattern p matches the whole of s.
    In p, '.' matches any single character and '*' matches zero or more of the preceding element.
    Every '*' is preceded by a valid character or '.'.
    Do not use the re module.
    """
    if not p:
        return not s

    first_match = bool(s) and (p[0] == s[0] or p[0] == '.')

    if len(p) >= 2 and p[1] == '*':
        return (regex_match(s, p[2:]) or
                (first_match and regex_match(s[1:], p)))
    else:
        return first_match and regex_match(s[1:], p[1:])

def factorial(n: int) -> int:
    """Return n! for a non-negative integer n, with 0! = 1. Raise ValueError if n is negative."""
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

from collections import deque

def sliding_max(nums: list[int], k: int) -> list[int]:
    """
    Return the maximum of each contiguous window of size k (1 <= k <= len(nums)), from left to right.
    The solution must run in O(n) time.
    """
    if not nums:
        return []

    if k <= 0:
        return []

    if k > len(nums):
        return [max(nums)]

    result = []
    dq = deque()  # Store indices

    for i in range(len(nums)):
        # Remove elements out of the window
        while dq and dq[0] <= i - k:
            dq.popleft()

        # Remove elements smaller than the current element
        while dq and nums[dq[-1]] <= nums[i]:
            dq.pop()

        dq.append(i)

        # The maximum element for the current window is at the front of the deque
        if i >= k - 1:
            result.append(nums[dq[0]])

    return result

