from collections import defaultdict

def topo_sort(n, edges):
    graph = defaultdict(list)
    indegree = [0] * n

    for u, v in edges:
        graph[u].append(v)
        indegree[v] += 1

    zero_indegree = [i for i in range(n) if indegree[i] == 0]
    order = []

    while zero_indegree:
        u = zero_indegree.pop(0)
        order.append(u)

        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                zero_indegree.append(v)

    if len(order) == n:
        return order
    else:
        return []

