def n_queens(n: int) -> int:
    def is_not_attacking(queens):
        for i in range(len(queens)):
            for j in range(i+1, len(queens)):
                if queens[i] == queens[j] or abs(queens[i] - queens[j]) == j - i:
                    return False
        return True

    def place_queens(row, queens):
        if row == n:
            return 1
        total = 0
        for col in range(n):
            queens[row] = col
            if is_not_attacking(queens):
                total += place_queens(row + 1, queens)
        return total

    return place_queens(0, [-1] * n)

