def largest_rectangle(heights: list[int]) -> int:
    stack = []  # Stack to keep track of the indices of the histogram bars
    max_area = 0
    index = 0  # Current index

    while index < len(heights):
        if not stack or heights[stack[-1]] <= heights[index]:
            stack.append(index)
            index += 1
        else:
            top_of_stack = stack.pop()
            # If stack is not empty, calculate the area
            if stack:
                area = (heights[index] * (index - stack[-1] - 1))
            else:
                area = (heights[index] * index)
            max_area = max(max_area, area)

    # Now pop the remaining bars from the stack and calculate area
    while stack:
        top_of_stack = stack.pop()
        if stack:
            area = (heights[top_of_stack] * (index - stack[-1] - 1))
        else:
            area = (heights[top_of_stack] * index)
        max_area = max(max_area, area)
        index += 1

    return max_area

