    misses = 0

    for key in requests:
        if key in cache:
            cache.remove(key)
            cache.append(key)
        else:
            misses += 1
            if len(cache) == capacity:
                cache.pop(0)  # Evict the least recently used key (the first in the list)
            cache.append(key)

    return misses

