def prime_factors(n: int) -> list[int]:
    if n < 2:
        raise ValueError("Input must be an integer greater than 1")

    factors = []
    divisor = 2

    while n > 1:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1

        if divisor * divisor > n:
            if n > 1:
                factors.append(n)
                break

    return factors

