    while left <= right:
        mid = left + (right - left) // 2
        if nums[mid] == target:
            while mid > 0 and nums[mid - 1] == target:
                mid -= 1
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def paths_with_obstacles(grid: list[list[int]]) -> int:
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0
    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1
    for i in range(1, m):
        dp[i][0] = dp[i-1][0] if grid[i-1][0] == 1 else 0
    for j in range(1, n):
        dp[0][j] = dp[0][j-1] if grid[0][j-1] == 1 else 0
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
    return dp[-1][-1]

def lis_length(nums: list[int]) -> int:
    from bisect import bisect_left

    def longest_increasing_subsequence_length(arr):
        sub = [arr[0]]
        for num in arr[1:]:
            if num > sub[-1]:
                sub.append(num)
            else:
                index = bisect_left(sub, num)
                sub[index] = num
        return len(sub)

    return longest_increasing_subsequence_length(nums)

