def evaluate(expr: str) -> int:
    def get_precedence(op):
        if op == '+' or op == '-':
            return 1
        if op == '*' or op == '/':
            return 2
        return 0

    def apply_operation(a, b, op):
        if op == '+': return a + b
        if op == '-': return a - b
        if op == '*': return a * b
        if op == '/': return int(a / b)  # Truncate toward zero

    def parse_expression(expr):
        num = 0
        current_op = None
        stack = []
        num_stack = []
        i = 0
        while i < len(expr):
            char = expr[i]
            if char.isdigit():
                num = num * 10 + int(char)
            elif char in '+-*/':
                if current_op:
                    stack.append(apply_operation(num_stack.pop(), num, current_op))
                num_stack.append(num)
                num = 0
                current_op = char
            elif char == '(':
                j = i + 1
                count = 1
                while j < len(expr):
                    if expr[j] == '(':
                        count += 1
                    elif expr[j] == ')':
                        count -= 1
                    if count == 0:
                        break
                    j += 1
                num = evaluate(expr[i+1:j])
                i = j
            i += 1
        if current_op:
            stack.append(apply_operation(num_stack.pop(), num, current_op))
        while num_stack:
            stack.append(num_stack.pop())
        return sum(stack)

    return parse_expression(expr)

