from typing import List

def sliding_max(nums: List[int], k: int) -> List[int]:
    if not nums or k <= 0 or k > len(nums):
        return []

    deq = deque()
    result = []

    for i in range(len(nums)):
        # Remove indices that are out of the bounds of the current window
        if deq and deq[0] < i - k + 1:
            deq.popleft()

        # Remove elements from the back that are less than or equal to nums[i]
        while deq and nums[deq[-1]] <= nums[i]:
            deq.pop()

        # Add the current element's index to the deque
        deq.append(i)

        # Append the maximum for the current window to the result
        if i >= k - 1:
            result.append(nums[deq[0]])

    return result

