    for i in range(len(nums) - 1, 0, -1):
        if nums[i] > nums[i - 1]:
            pivot_index = i - 1
            break

    if pivot_index == -1:
        return sorted(nums)

    for i in range(len(nums) - 1, pivot_index, -1):
        if nums[i] > nums[pivot_index]:
            nums[i], nums[pivot_index] = nums[pivot_index], nums[i]
            break

