def caesar_shift(s: str, k: int) -> str:
    result = []
    k = k % 26  # Normalize k to be within the range of 0 to 25

    for char in s:
        if 'A' <= char <= 'Z':
            # Shift uppercase letter
            new_char = chr((ord(char) - 65 + k) % 26 + 65)
            result.append(new_char)
        elif 'a' <= char <= 'z':
            # Shift lowercase letter
            new_char = chr((ord(char) - 97 + k) % 26 + 97)
            result.append(new_char)
        else:
            # Non-letter characters remain unchanged
            result.append(char)

    return ''.join(result)

