def sliding_max(nums: list[int], k: int) -> list[int]:
    if not nums or k <= 0:
        return []

    n = len(nums)
    if k > n:
        return []

    deq = deque()
    result = []

    for i in range(n):
        # Remove indices that are out of the bounds of the current window
        if deq and deq[0] == i - k:
            deq.popleft()

        # Remove elements from the deque that are less than the current element
        while deq and nums[i] > nums[deq[-1]]:
            deq.pop()

        # Add the current element's index to the deque
        deq.append(i)

        # Append the maximum for the current window to the result
        if i >= k - 1:
            result.append(nums[deq[0]])

    return result

def min_coins(coins: list[int], amount: int) -> int:
    if amount == 0:
        return 0

    dp = [float('inf')] * (amount + 1)
    dp[0] = 0

    for current_amount in range(1, amount + 1):
        for coin in coins:
            if coin <= current_amount:
                dp[current_amount] = min(dp[current_amount], 1 + dp[current_amount - coin])

    return dp[amount] if dp[amount] != float('inf') else -1

