def n_queens(n: int) -> int:
    def is_safe(queen_positions, row, col):
        for r in range(row):
            c = queen_positions[r]
            if c == col or c - r == col - row or c + r == col + row:
                return False
        return True

    def solve(row, queen_positions):
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if is_safe(queen_positions, row, col):
                queen_positions[row] = col
                count += solve(row + 1, queen_positions)
        return count

    return solve(0, [-1] * n)

