def evaluate(expr: str) -> int:
    import re

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(int(left / right))

    def apply_parentheses(operators, values):
        for i in range(len(operators)):
            if operators[i] == '(':
                op_index = i
                values_index = len(values) - 1
                for j in range(i + 1, len(operators)):
                    if operators[j] == ')':
                        right = values.pop()
                        left = values.pop()
                        values.append(int(left / right))
                        del operators[j]
                        del operators[op_index]
                        break
        return apply_operator(operators, values)

    def evaluate_expression(expr: str) -> int:
        operators = []
        values = []
        tokens = re.findall(r'\d+|[+\-*/()]', expr)

        for token in tokens:
            if token.isdigit():
                values.append(int(token))
            elif token == '(':
                operators.append(token)
            elif token in '+-*/':
                while (operators and operators[-1] in '*/' and
                       (operators[-1] == '/' and values[-1] == 0 or
                        operators[-1] == '+' or operators[-1] == '-')):
                    apply_operator(operators, values)
                operators.append(token)
            elif token == ')':
                apply_parentheses(operators, values)

        while operators:
            apply_operator(operators, values)

        return values[0]

    return evaluate_expression(expr)

