    from collections import deque, defaultdict

    adj_list = defaultdict(list)
    in_degree = [0] * n

    for u, v in edges:
        adj_list[u].append(v)
        in_degree[v] += 1

    queue = deque([u for u in range(n) if in_degree[u] == 0])
    topo_order = []

    while queue:
        u = queue.popleft()
        topo_order.append(u)

        for v in adj_list[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(topo_order) == n:
        return topo_order
    else:
        return []

