def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty duration string")

    unit_to_seconds = {
        'd': 24 * 3600,
        'h': 3600,
        'm': 60,
        's': 1
    }

    total_seconds = 0
    i = 0
    while i < len(s):
        while i < len(s) and not s[i].isdigit():
            i += 1
        if i >= len(s):
            raise ValueError("Malformed duration string")

        start = i
        while i < len(s) and s[i].isdigit():
            i += 1
        number = int(s[start:i])

        if i >= len(s):
            raise ValueError("Malformed duration string")
        unit = s[i]
        i += 1

        if unit not in unit_to_seconds:
            raise ValueError(f"Invalid unit '{unit}' in duration string")

        total_seconds += number * unit_to_seconds[unit]

    return total_seconds

