import heapq

def dijkstra(n: int, edges: list[tuple[int, int, int]], src: int) -> list[int]:
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    distances = [float('inf')] * n
    distances[src] = 0
    pq = [(0, src)]

    while pq:
        current_dist, u = heapq.heappop(pq)

        if current_dist > distances[u]:
            continue

        for v, weight in graph[u]:
            distance = current_dist + weight
            if distance < distances[v]:
                distances[v] = distance
                heapq.heappush(pq, (distance, v))

    return [-1 if dist == float('inf') else dist for dist in distances]

def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Input string is empty")

    # Define unit multipliers
    unit_multipliers = {
        'd': 24 * 60 * 60,  # days to seconds
        'h': 60 * 60,        # hours to seconds
        'm': 60,            # minutes to seconds
        's': 1             # seconds
    }

    # Regular expression to match <integer><unit> parts
    pattern = re.compile(r'(\d+)([dhms])')

    # Find all matches in the input string
    matches = pattern.findall(s)

    if not matches:
        raise ValueError("Malformed input string")

    total_seconds = 0

    for number, unit in matches:
        if unit not in unit_multipliers:
            raise ValueError(f"Invalid unit: {unit}")
        total_seconds += int(number) * unit_multipliers[unit]

    return total_seconds

