def topo_sort(n: int, edges: list[tuple[int, int]]) -> list[int]:
    graph = [[] for _ in range(n)]
    indegree = [0] * n

    for u, v in edges:
        graph[u].append(v)
        indegree[v] += 1

    q = deque([u for u in range(n) if indegree[u] == 0])
    ordering = []

    while q:
        u = q.popleft()
        ordering.append(u)

        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                q.append(v)

    if len(ordering) != n:
        return []

    return ordering

