def topo_sort(n: int, edges: list[tuple[int, int]]) -> list[int]:
    # Build the adjacency list and indegree array
    adj = [[] for _ in range(n)]
    indegree = [0] * n
    for u, v in edges:
        adj[u].append(v)
        indegree[v] += 1

    # Initialize a queue with nodes having indegree 0
    queue = []
    for i in range(n):
        if indegree[i] == 0:
            queue.append(i)

    # Sort the queue to ensure lexicographical order
    queue.sort()

    topo_order = []
    while queue:
        u = queue.pop(0)
        topo_order.append(u)
        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)
        queue.sort()

    if len(topo_order) == n:
        return topo_order
    else:
        return []

