def evaluate(expr: str) -> int:
    def tokenize(s):
        tokens = []
        i = 0
        while i < len(s):
            if s[i] == ' ':
                i += 1
                continue
            if s[i] in '+-*/()':
                tokens.append(s[i])
                i += 1
            else:
                num = ''
                while i < len(s) and s[i].isdigit():
                    num += s[i]
                    i += 1
                tokens.append(num)
        return tokens

    def shunting_yard(tokens):
        output = []
        operators = []
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        for token in tokens:
            if token.isdigit():
                output.append(token)
            elif token in precedence:
                while (operators and operators[-1] != '(' and
                       precedence[operators[-1]] >= precedence[token]):
                    output.append(operators.pop())
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators[-1] != '(':
                    output.append(operators.pop())
                operators.pop()
        while operators:
            output.append(operators.pop())
        return output

    def evaluate_rpn(rpn):
        stack = []
        for token in rpn:
            if token.isdigit():
                stack.append(int(token))
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a // b)
        return stack[0]

    tokens = tokenize(expr)
    rpn = shunting_yard(tokens)
    return evaluate_rpn(rpn)

