def topo_sort(n: int, edges: list[tuple[int, int]]) -> list[int]:
    # Build the adjacency list and in-degree count
    adj = [[] for _ in range(n)]
    in_degree = [0] * n
    for u, v in edges:
        adj[u].append(v)
        in_degree[v] += 1

    # Initialize the priority queue with nodes having in-degree 0
    heap = []
    for node in range(n):
        if in_degree[node] == 0:
            heapq.heappush(heap, node)

    topo_order = []
    while heap:
        u = heapq.heappop(heap)
        topo_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(topo_order) == n:
        return topo_order
    else:
        return []

