def knapsack(weights: list[int], values: list[int], capacity: int) -> int:
    n = len(weights)
    # Create a DP table where dp[i][w] represents the maximum value achievable with the first i items and a maximum weight of w
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(1, capacity + 1):
            if weights[i - 1] <= w:
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - weights[i - 1]] + values[i - 1])
            else:
                dp[i][w] = dp[i - 1][w]

    return dp[n][capacity]

import heapq

def dijkstra(n: int, edges: list[tuple[int, int, int]], src: int) -> list[int]:
    # Initialize distances with infinity and set the source distance to 0
    distances = [float('inf')] * n
    distances[src] = 0

    # Priority queue to store (distance, node) tuples
    heap = []
    heapq.heappush(heap, (0, src))

    # Dictionary to map node to its adjacent nodes and weights
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append((v, w))

    while heap:
        current_distance, current_node = heapq.heappop(heap)

        # If the current distance is greater than the recorded distance, skip
        if current_distance > distances[current_node]:
            continue

        # Explore all adjacent nodes
        if current_node in graph:
            for neighbor, weight in graph.get(current_node, []):
                distance = current_distance + weight
                # If a shorter path is found
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(heap, (distance, neighbor))

    # Replace infinity with -1 for unreachable nodes
    distances = [-1 if d == float('inf') else d for d in distances]
    return distances

def paths_with_obstacles(grid: list[list[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    # If the start or end cell is blocked, return 0
    if grid[0][0] == 1 or grid[rows-1][cols-1] == 1:
        return 0

    # Create a DP table initialized with 0s
    dp = [[0 for _ in range(cols)] for _ in range(rows)]
    dp[0][0] = 1  # Starting point

    # Fill the DP table
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                dp[i][j] = 0
                continue
            if i > 0:
                dp[i][j] += dp[i-1][j]
            if j > 0:
                dp[i][j] += dp[i][j-1]

    return dp[rows-1][cols-1]
