def knapsack(weights: list[int], values: list[int], capacity: int) -> int:
    n = len(weights)
    dp = [[0 for _ in range(capacity + 1)] for _ in range(n + 1)]
    for i in range(1, n + 1):
        for w in range(1, capacity + 1):
            if weights[i-1] <= w:
                dp[i][w] = max(dp[i-1][w], dp[i-1][w-weights[i-1]] + values[i-1])
            else:
                dp[i][w] = dp[i-1][w]
    return dp[n][capacity]

import heapq

def dijkstra(n: int, edges: list[tuple[int, int, int]], src: int) -> list[int]:
    distances = [float('infinity')] * n
    distances[src] = 0
    heap = []
    heapq.heappush(heap, (0, src))
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
    while heap:
        current_dist, current_node = heapq.heappop(heap)
        if current_dist > distances[current_node]:
            continue
        for neighbor, weight in adj[current_node]:
            distance = current_dist + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(heap, (distance, neighbor))
    distances = [-1 if d == float('infinity') else d for d in distances]
    return distances

def paths_with_obstacles(grid: list[list[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    if grid[0][0] == 1 or grid[rows - 1][cols - 1] == 1:
        return 0

    dp = [[0 for _ in range(cols)] for _ in range(rows)]
    dp[0][0] = 1

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i - 1][j]
                if j > 0:
                    dp[i][j] += dp[i][j - 1]

    return dp[rows - 1][cols - 1]

def trapped_water(heights: list[int]) -> int:
    if not heights:
        return 0

    left, right = 0, len(heights) - 1
    left_max, right_max = heights[left], heights[right]
    trapped_water = 0

    while left < right:
        if heights[left] <= heights[right]:
            left += 1
            left_max = max(left_max, heights[left])
            trapped_water += left_max - heights[left]
        else:
            right -= 1
            right_max = max(right_max, heights[right])
            trapped_water += right_max - heights[right]

    return trapped_water

def balanced_brackets(s: str) -> bool:
    stack = []
    bracket_pairs = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in bracket_pairs.values():
            stack.append(char)
        elif char in bracket_pairs.keys():
            if not stack or stack[-1] != bracket_pairs[char]:
                return False
            stack.pop()

    return len(stack) == 0

